import{_ as a,C as n,o as i,c as s,j as o,a as u,E as r,a2 as c}from"./chunks/framework.BiXHgXAn.js";const y=JSON.parse('{"title":"GitHub Secure Open Source Fund","description":"Task participated in session 4 of the GitHub Secure Open Source program.","frontmatter":{"title":"GitHub Secure Open Source Fund","sidebarTitle":"GitHub SOSF","description":"Task participated in session 4 of the GitHub Secure Open Source program.","author":"andreynering","date":"2026-08-15T00:00:00.000Z","tags":["github","security"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/github-secure-open-source-program.md","filePath":"next/blog/github-secure-open-source-program.md"}'),p={name:"blog/github-secure-open-source-program.md"};function d(l,e,h,m,b,f){const t=n("AuthorCard");return i(),s("div",null,[e[0]||(e[0]=o("h1",{id:"github-secure-open-source-fund",tabindex:"-1"},[u("GitHub Secure Open Source Fund "),o("a",{class:"header-anchor",href:"#github-secure-open-source-fund","aria-label":'Permalink to "GitHub Secure Open Source Fund"'},"​")],-1)),r(t,{author:"andreynering"}),r(t,{author:"pd93"}),r(t,{author:"vmaerten"}),e[1]||(e[1]=c('<p>Did you know that GitHub has a special program to fund security in open source? It&#39;s the <a href="https://github.com/open-source/github-secure-open-source-fund" target="_blank" rel="noreferrer">GitHub Secure Open Source Fund</a>. We were selected to participate in session 4 that happened in May 2026 and it was really special for us.</p><p>71 maintainers from 50 different open source projects and across 22 countries were selected to participate in the program. It was amazing to meet so many maintainers from other critical open source projects to learn how to make the open source software ecosystem more secure. We really acquired a meaningful amount of knowledge about security and had the enjoyed opportunity to ask questions and interact with both the GitHub Security Lab team and the other maintainers.</p><p>Some of the topics we learned about:</p><ul><li>How to make CI and GitHub Actions more secure</li><li>How to handle dependency updates in a secure way</li><li>How to handle vulnerability reports</li><li>How to use tools like CodeQL to make code more secure</li><li>How to better review code contributions to avoid introducing security issues</li><li>Many more...</li></ul><p>During the program we took action to make Task more secure, especially with regard to CI. Since then, we also handled a few different vulnerability reports, and having the knowledge to do that definitely helped us in the process.</p><p>We also formalized our security policies and documented them in a new security section of our website. See both our <a href="https://taskfile.dev/docs/security/incident-response-plan" target="_blank" rel="noreferrer">incident response plan</a> and our <a href="https://taskfile.dev/docs/security/threat-model" target="_blank" rel="noreferrer">threat model</a>.</p><p>Many thanks to the GitHub Security Lab for this opportunity! Want to read more? GitHub wrote a blog post about session 4 that <a href="https://github.blog/open-source/maintainers/what-50-open-source-projects-taught-us-about-security-in-the-ai-era/" target="_blank" rel="noreferrer">you can read here</a>.</p>',7))])}const S=a(p,[["render",d]]);export{y as __pageData,S as default};
